let texto = $json.output || '{}';
let dados = {};
try {
  const limpo = texto.replace(/```json|```/g, '').trim();
  dados = JSON.parse(limpo);
} catch (e) {
  dados = { erro_parse: true, texto_bruto: texto };
}
const ctx = $('Montar Contexto').item.json;
return [{ json: {
  atendimento_id: ctx.atendimento_id,
  empresa_id: ctx.empresa_id,
  modelo_usado: 'gpt-4o',
  resultado: dados.resultado || 'sem_solucao',
  pedido_id: (ctx.contexto && ctx.contexto.fatos_pre_computados && ctx.contexto.fatos_pre_computados.pedido) ? ctx.contexto.fatos_pre_computados.pedido.id : null,
  qualidade_score: dados.qualidade_score ?? null,
  teve_alucinacao: !!dados.teve_alucinacao,
  teve_informacao_incorreta: !!dados.teve_informacao_incorreta,
  resposta_incompleta: !!dados.resposta_incompleta,
  resposta_confusa: !!dados.resposta_confusa,
  friccao_score: dados.friccao_score ?? null,
  qtd_perguntas_desnecessarias: dados.qtd_perguntas_desnecessarias || 0,
  qtd_reformulacoes_cliente: dados.qtd_reformulacoes_cliente || 0,
  cliente_repetiu_informacao: !!dados.cliente_repetiu_informacao,
  sentimento_cliente: dados.sentimento_cliente || 'indeterminado',
  tools_usadas_incorretamente: JSON.stringify(dados.tools_usadas_incorretamente || []),
  tools_faltantes: JSON.stringify(dados.tools_faltantes || []),
  tools_desnecessarias: JSON.stringify(dados.tools_desnecessarias || []),
  teve_erro_tecnico: !!dados.teve_erro_tecnico,
  teve_intencao_compra: !!dados.teve_intencao_compra,
  chegou_no_carrinho: !!dados.chegou_no_carrinho,
  venda_perdida: !!dados.venda_perdida,
  venda_perdida_motivo: dados.venda_perdida_motivo || null,
  fatos_observados: JSON.stringify(dados.fatos_observados || []),
  problemas_detectados: JSON.stringify(dados.problemas_detectados || []),
  resumo: dados.resumo || '(auditor não retornou resumo)',
  recomendacao: dados.recomendacao || null,
  metadata: JSON.stringify(dados.erro_parse ? { erro_parse: true, texto_bruto: dados.texto_bruto } : {})
} }];

